import { ColumnView, ListView, type ColumnViewColumn, type ListItem, type ListSection } from "@gtkx/components";
import * as Gtk from "@gtkx/gi/gtk";
import { GtkLabel, GtkScrolledWindow } from "@gtkx/jsx/gtk";
import { render, screen, within } from "@gtkx/testing";
import { describe, expect, it } from "vitest";

type Row = { name: string };

const leaf = (n: string): ListItem<Row> => ({ id: n, value: { name: n } });

const treeItems: ListItem<Row>[] = [
    { id: "p1", value: { name: "p1" }, children: [leaf("c1"), leaf("c2")] },
    leaf("x1"),
];

const sections: ListSection<string, Row>[] = [{ id: "s1", value: "One", data: treeItems }];

const cols: ColumnViewColumn<Row>[] = [
    { id: "name", title: "Name", renderCell: ({ item }) => <GtkLabel>{item.name}</GtkLabel> },
];

const renderItem = ({ item }: { item: Row }) => <GtkLabel>{item.name}</GtkLabel>;
const renderHeader = ({ section }: { section: string }) => <GtkLabel>{`H:${section}`}</GtkLabel>;

const labelsIn = (w: Gtk.Widget): string =>
    within(w).queryAllByRole(Gtk.AccessibleRole.LABEL, { as: Gtk.Label }).map((l) => l.label).join("");

const listRows = (): string[] => screen.queryAllByRole(Gtk.AccessibleRole.LIST_ITEM).map(labelsIn);
const tableRows = (): string[] => screen.queryAllByRole(Gtk.AccessibleRole.ROW).map(labelsIn);

const countExpanders = (root: Gtk.Widget): number => {
    let found = 0;
    const walk = (w: Gtk.Widget | null) => {
        if (!w) return;
        if (w instanceof Gtk.TreeExpander) found += 1;
        let child = w.getFirstChild();
        while (child) { walk(child); child = child.getNextSibling(); }
    };
    walk(root);
    return found;
};

describe("sections drop ListItem.children", () => {
    it("ListView, items: the tree expands (control)", async () => {
        const { container } = await render(
            <GtkScrolledWindow widthRequest={300} heightRequest={500} vexpand hexpand>
                <ListView<Row> items={treeItems} expandedIds={["p1"]} renderItem={renderItem} />
            </GtkScrolledWindow>,
        );
        expect({ rows: listRows(), expanders: countExpanders(container as never) })
            .toEqual({ rows: ["p1", "c1", "c2", "x1"], expanders: 4 });
    });

    it("ListView, sections: the same tree never expands", async () => {
