import { css, cx } from "@gtkx/css";
import { GtkLabel } from "@gtkx/jsx/gtk";
import { render, screen } from "@gtkx/testing";
import { describe, expect, it } from "vitest";

const loaded: string[] = [];
const original = Gtk.CssProvider.prototype.loadFromString;

Gtk.CssProvider.prototype.loadFromString = function patched(this: Gtk.CssProvider, text: string) {
    loaded.push(text);

    return original.call(this, text);
};

const settle = async (): Promise<void> => {
    for (let i = 0; i < 5; i++) {
        await Promise.resolve();
    }

    await new Promise((resolve) => setTimeout(resolve, 80));
};

const show = (rgba: { red: number; green: number; blue: number }): string =>
    `rgb(${String(Math.round(rgba.red * 255))}, ${String(Math.round(rgba.green * 255))}, ${String(Math.round(rgba.blue * 255))})`;

const rulesFor = (className: string): string[] =>
    (loaded.at(-1) ?? "").split("\n").filter((line) => line.includes(className));

describe("cx merging", () => {
    it("keeps both declarations when the last one has no trailing semicolon", async () => {
        const sizing = css`
            min-width: 48px;
            min-height: 32px
        `;
        const tint = css`
            color: rgb(0, 0, 255)
        `;
        const classes = cx(sizing, tint);

        await render(<GtkLabel cssClasses={classes}>merge</GtkLabel>);

        const label = await screen.findByText("merge");

        await settle();
        console.log("sizing alone ->", JSON.stringify(rulesFor(sizing)));
        console.log("tint alone   ->", JSON.stringify(rulesFor(tint)));
        console.log("merged       ->", JSON.stringify(rulesFor(classes.at(-1) ?? "?")));
        console.log("color        ->", show(label.getColor()), "(want blue)");
        console.log(
