        expect(show(label.getColor())).toBe("rgb(0, 0, 255)");
        expect(label.measure(Gtk.Orientation.HORIZONTAL, -1)[0]).toBe(48);
    });

    it("control: the same two styles with trailing semicolons merge correctly", async () => {
