import { css } from "@gtkx/css";
import { GtkApplication, GtkApplicationWindow, GtkLabel } from "@gtkx/jsx/gtk";
import { quit } from "@gtkx/react";
import { useEffect } from "react";

const fromData = `"Sans${String.fromCodePoint(0)}"`;

const MainWindow = () => {
    let name = "";

    try {
        name = css`
            font-family: ${fromData};
        `;
        console.log("css() returned normally:", name);
    } catch (error) {
        console.log("css() threw and was caught:", error);
    }

    useEffect(() => {
        const handle = setTimeout(() => {
            console.log("still alive, quitting");
            quit();
        }, 2000);

        return () => {
            clearTimeout(handle);
        };
    }, []);

    return (
        <GtkApplicationWindow title="min" onCloseRequest={quit}>
            <GtkLabel cssClasses={[name]}>min</GtkLabel>
        </GtkApplicationWindow>
    );
};

export const App = () => (
    <GtkApplication>
        <MainWindow />
    </GtkApplication>
);

